"use strict";(globalThis.webpackChunkcpp_linux_playground=globalThis.webpackChunkcpp_linux_playground||[]).push([[8581],{5610(e){e.exports=JSON.parse('{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Getting Started with C++ Linux Playground","href":"/cpp-linux-playground/docs/intro","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","items":[{"type":"link","label":"Setting Up Your Environment","href":"/cpp-linux-playground/docs/getting-started/setup","docId":"getting-started/setup","unlisted":false},{"type":"link","label":"Project Overview","href":"/cpp-linux-playground/docs/getting-started/project-overview","docId":"getting-started/project-overview","unlisted":false},{"type":"link","label":"Docker Development Setup","href":"/cpp-linux-playground/docs/getting-started/docker-setup","docId":"getting-started/docker-setup","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Phase 1: Syntax and Tool Familiarization","items":[{"type":"link","label":"Phase 1: Syntax and Tool Familiarization","href":"/cpp-linux-playground/docs/phase1/intro","docId":"phase1/intro","unlisted":false},{"type":"link","label":"CLI Tools Implementation","href":"/cpp-linux-playground/docs/phase1/cli-tools","docId":"phase1/cli-tools","unlisted":false},{"type":"link","label":"JSON Parser Implementation","href":"/cpp-linux-playground/docs/phase1/json-parser","docId":"phase1/json-parser","unlisted":false},{"type":"link","label":"Multi-threaded Logger Implementation","href":"/cpp-linux-playground/docs/phase1/logger","docId":"phase1/logger","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Phase 2: System Programming","items":[{"type":"link","label":"Phase 2: System Programming","href":"/cpp-linux-playground/docs/phase2/intro","docId":"phase2/intro","unlisted":false},{"type":"link","label":"Memory Pool Allocator Implementation","href":"/cpp-linux-playground/docs/phase2/memory-pool","docId":"phase2/memory-pool","unlisted":false},{"type":"link","label":"Process Management Tool Implementation","href":"/cpp-linux-playground/docs/phase2/process-manager","docId":"phase2/process-manager","unlisted":false},{"type":"link","label":"Multi-threaded Downloader Implementation","href":"/cpp-linux-playground/docs/phase2/threaded-downloader","docId":"phase2/threaded-downloader","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Phase 3: Network Programming","items":[{"type":"link","label":"Phase 3: Network Programming","href":"/cpp-linux-playground/docs/phase3/intro","docId":"phase3/intro","unlisted":false},{"type":"link","label":"TCP Multi-threaded Chat Room Implementation","href":"/cpp-linux-playground/docs/phase3/tcp-chat-room","docId":"phase3/tcp-chat-room","unlisted":false},{"type":"link","label":"HTTP Static File Server Implementation","href":"/cpp-linux-playground/docs/phase3/http-server","docId":"phase3/http-server","unlisted":false},{"type":"link","label":"TCP File Transfer Server Implementation","href":"/cpp-linux-playground/docs/phase3/tcp-file-transfer","docId":"phase3/tcp-file-transfer","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Phase 4: Comprehensive Practice","items":[{"type":"link","label":"Phase 4: Comprehensive Practice","href":"/cpp-linux-playground/docs/phase4/intro","docId":"phase4/intro","unlisted":false},{"type":"link","label":"mini-Redis Implementation","href":"/cpp-linux-playground/docs/phase4/mini-redis","docId":"phase4/mini-redis","unlisted":false},{"type":"link","label":"mini-Search Implementation","href":"/cpp-linux-playground/docs/phase4/mini-search","docId":"phase4/mini-search","unlisted":false},{"type":"link","label":"High-concurrency Crawler Implementation","href":"/cpp-linux-playground/docs/phase4/crawler","docId":"phase4/crawler","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Development Standards","items":[{"type":"link","label":"Code Style and Formatting Standards","href":"/cpp-linux-playground/docs/standards/code-style","docId":"standards/code-style","unlisted":false},{"type":"link","label":"Testing Standards","href":"/cpp-linux-playground/docs/standards/testing","docId":"standards/testing","unlisted":false},{"type":"link","label":"Git Commit Standards","href":"/cpp-linux-playground/docs/standards/git-commit","docId":"standards/git-commit","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"getting-started/docker-setup":{"id":"getting-started/docker-setup","title":"Docker Development Setup","description":"Using Docker for development ensures a consistent environment across different platforms and simplifies dependency management for the Linux C++ Backend Development Playground.","sidebar":"tutorialSidebar"},"getting-started/project-overview":{"id":"getting-started/project-overview","title":"Project Overview","description":"The Linux C++ Backend Development Playground is structured into four progressive phases, each designed to build upon the previous one and introduce increasingly complex concepts and challenges.","sidebar":"tutorialSidebar"},"getting-started/setup":{"id":"getting-started/setup","title":"Setting Up Your Environment","description":"Learn how to set up your development environment for the Linux C++ Backend Development Playground project.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Getting Started with C++ Linux Playground","description":"Welcome to the Linux C++ Backend Development Playground! This project is designed for engineers with backend development experience who want to master modern C++, system programming, network programming, and performance optimization through progressive hands-on projects.","sidebar":"tutorialSidebar"},"phase1/cli-tools":{"id":"phase1/cli-tools","title":"CLI Tools Implementation","description":"Implement simplified versions of the classic Unix command-line tools: ls, grep, and wc. These projects will help you master basic C++ concepts and file system operations.","sidebar":"tutorialSidebar"},"phase1/intro":{"id":"phase1/intro","title":"Phase 1: Syntax and Tool Familiarization","description":"Phase 1 focuses on familiarizing you with modern C++20 syntax and building foundational command-line tools. This phase builds practical skills with the language while implementing simplified versions of common Unix utilities.","sidebar":"tutorialSidebar"},"phase1/json-parser":{"id":"phase1/json-parser","title":"JSON Parser Implementation","description":"Build a lightweight, high-performance JSON parser library that can parse JSON strings and provide convenient access to their values. This project introduces you to recursive descent parsing and object-oriented design in C++.","sidebar":"tutorialSidebar"},"phase1/logger":{"id":"phase1/logger","title":"Multi-threaded Logger Implementation","description":"Develop a high-performance, thread-safe logging system that can handle concurrent write requests from multiple threads. This project introduces you to concurrent programming concepts in C++.","sidebar":"tutorialSidebar"},"phase2/intro":{"id":"phase2/intro","title":"Phase 2: System Programming","description":"Phase 2 focuses on Linux system programming, where you\'ll learn to interact directly with the operating system through system calls. This phase covers process management, thread synchronization, memory management, and other low-level programming concepts.","sidebar":"tutorialSidebar"},"phase2/memory-pool":{"id":"phase2/memory-pool","title":"Memory Pool Allocator Implementation","description":"Develop a high-performance custom memory allocator that uses memory pools to reduce allocation overhead and improve cache locality. This project explores advanced memory management techniques and performance optimization.","sidebar":"tutorialSidebar"},"phase2/process-manager":{"id":"phase2/process-manager","title":"Process Management Tool Implementation","description":"Build a simplified process monitoring tool similar to ps or top that can list running processes, monitor their resource usage, and provide process control capabilities. This project introduces you to Linux process management and system information retrieval.","sidebar":"tutorialSidebar"},"phase2/threaded-downloader":{"id":"phase2/threaded-downloader","title":"Multi-threaded Downloader Implementation","description":"Build a high-performance, multi-threaded file download application that can download files in chunks simultaneously and reassemble them. This project introduces you to concurrent I/O operations and file management in a system programming context.","sidebar":"tutorialSidebar"},"phase3/http-server":{"id":"phase3/http-server","title":"HTTP Static File Server Implementation","description":"Build a high-performance HTTP server that serves static files to clients. This project explores HTTP protocol handling, file I/O operations, and proper web server behavior.","sidebar":"tutorialSidebar"},"phase3/intro":{"id":"phase3/intro","title":"Phase 3: Network Programming","description":"Phase 3 focuses on network programming, where you\'ll build applications that communicate over networks using TCP/IP and HTTP protocols. This phase covers socket programming, concurrent network I/O, and building robust network services.","sidebar":"tutorialSidebar"},"phase3/tcp-chat-room":{"id":"phase3/tcp-chat-room","title":"TCP Multi-threaded Chat Room Implementation","description":"Build a real-time, multi-threaded chat application that allows multiple users to connect and exchange messages simultaneously. This project introduces you to socket programming, concurrent client handling, and real-time communication protocols.","sidebar":"tutorialSidebar"},"phase3/tcp-file-transfer":{"id":"phase3/tcp-file-transfer","title":"TCP File Transfer Server Implementation","description":"Build a TCP-based file transfer server that allows clients to upload and download files. This project explores binary data transmission, file I/O operations, and protocol design for non-text data.","sidebar":"tutorialSidebar"},"phase4/crawler":{"id":"phase4/crawler","title":"High-concurrency Crawler Implementation","description":"Build a high-performance web crawler that can efficiently crawl and index web pages from multiple domains. This project combines network programming, concurrency, and data processing techniques.","sidebar":"tutorialSidebar"},"phase4/intro":{"id":"phase4/intro","title":"Phase 4: Comprehensive Practice","description":"Phase 4 integrates all the skills learned in the previous phases to build complete, production-quality applications. These projects combine system programming, network programming, and performance optimization techniques into comprehensive solutions.","sidebar":"tutorialSidebar"},"phase4/mini-redis":{"id":"phase4/mini-redis","title":"mini-Redis Implementation","description":"Build a simplified Redis-compatible key-value store that supports common data types and operations. This project combines network programming with efficient data structures and memory management techniques.","sidebar":"tutorialSidebar"},"phase4/mini-search":{"id":"phase4/mini-search","title":"mini-Search Implementation","description":"Build a simplified search engine that can index documents and perform full-text search operations. This project combines data structures, algorithms, and system programming to create an efficient search solution.","sidebar":"tutorialSidebar"},"standards/code-style":{"id":"standards/code-style","title":"Code Style and Formatting Standards","description":"Maintaining consistent code style is essential for readability, maintainability, and collaboration. This document outlines the coding standards for the Linux C++ Backend Development Playground project.","sidebar":"tutorialSidebar"},"standards/git-commit":{"id":"standards/git-commit","title":"Git Commit Standards","description":"Maintaining clear and consistent commit history is crucial for project maintainability and collaboration. This document outlines the Git commit standards for the Linux C++ Backend Development Playground project.","sidebar":"tutorialSidebar"},"standards/testing":{"id":"standards/testing","title":"Testing Standards","description":"Comprehensive testing is essential for ensuring code quality, reliability, and maintainability in the Linux C++ Backend Development Playground project. This document outlines the testing standards and practices to follow.","sidebar":"tutorialSidebar"}}}')}}]);